pub assume_specification<'a, B: 'a + ?Sized + ToOwned>[ Cow::into_owned ](
    cow: Cow<'a, B>,
) -> (res: <B as ToOwned>::Owned)
    ensures
        cow matches Cow::Owned(owned) ==> res == owned,
;

pub assume_specification<T: Deref>[ Option::<T>::as_deref ](
    option: &Option<T>,
) -> (res: Option<&T::Target>)
    ensures
        match option {
            Some(value) => res is Some && call_ensures(
                <T as Deref>::deref,
                (value,),
                res->0,
            ),
            None => res is None,
        },
;

pub assume_specification<T: Deref, E>[ Result::<T, E>::as_deref ](
    result: &Result<T, E>,
) -> (res: Result<&T::Target, &E>)
    ensures
        match result {
            Ok(value) => res is Ok && call_ensures(
                <T as Deref>::deref,
                (value,),
                res->Ok_0,
            ),
            Err(error) => res is Err && res->Err_0 == error,
        },
;
